import copy
import unittest

from handoff_demo.journal import append_entry


class JournalHiddenTests(unittest.TestCase):
    def test_copy_on_write_preserves_nested_input(self):
        for balance, amount in [(40, 7), (0, -3), (100, 0)]:
            with self.subTest(balance=balance, amount=amount):
                state = {"balance": balance, "entries": [{"key": "old", "amount": 2}], "currency": "EUR"}
                before = copy.deepcopy(state)
                result = append_entry(state, "new", amount)
                self.assertEqual(state, before)
                self.assertIsNot(result, state)
                self.assertIsNot(result["entries"], state["entries"])
                self.assertEqual(result["balance"], balance + amount)
                self.assertEqual(result["entries"], before["entries"] + [{"key": "new", "amount": amount}])
                self.assertEqual(result["currency"], "EUR")

    def test_duplicate_is_a_noop_even_before_the_last_entry(self):
        state = {"balance": 15, "entries": [{"key": "first", "amount": 10}, {"key": "second", "amount": 5}]}
        before = copy.deepcopy(state)
        self.assertEqual(append_entry(state, "first", 10), before)
        self.assertEqual(state, before)

    def test_changed_payload_rejects_without_partial_mutation(self):
        state = {"balance": 15, "entries": [{"key": "first", "amount": 10}]}
        before = copy.deepcopy(state)
        with self.assertRaises(ValueError):
            append_entry(state, "first", 11)
        self.assertEqual(state, before)


if __name__ == "__main__":
    unittest.main()
